func TestJudgmentFlowUnclosedFenceReported(t *testing.T) {
	before := strings.Replace(judgmentFlowFixture, judgmentFlowDiagram+"\\n```\\n", judgmentFlowDiagram+"\\n", 1)
	after := "# 判定フロー\\n\\n## 決定表\\n\\n" + judgmentFlowTables + "\\n## 図\\n\\n```mermaid\\nflowchart TD\\n"
	for name, content := range map[string]string{"表より前": before, "表より後": after} {
