			judgmentFlowExpectOne(t, content, "のフェンスが閉じていません")
		})
	}
}

func TestWriteJudgmentFlowDiagramRefusesUnclosedFence(t *testing.T) {
	path := filepath.Join(t.TempDir(), "judgment-flow.md")
	content := "# 判定フロー\\n\\n## 決定表\\n\\n" + judgmentFlowTables + "\\n## 図\\n\\n```mermaid\\nflowchart TD\\n"
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
